// ============================================================================
//  W I N D – U P   —  a one-minute short film, directed in three.js
//
//  A wind-up tin mouse gets loose in a child's bedroom at golden hour.
//  The resident plush cat gives chase: around the rug, under the bed,
//  through a pile of building blocks — until the spring runs out.
//
//  Everything is procedural: set, props, characters, lighting, textures,
//  choreography, the 10-shot camera cut list, and the wind-up ticking.
// ============================================================================

import * as THREE from 'three';

// ----------------------------------------------------------------------------
// small utilities
// ----------------------------------------------------------------------------
const FILM_LENGTH = 60;

function clamp(x, a, b) { return Math.max(a, Math.min(b, x)); }
function lerp(a, b, t) { return a + (b - a) * t; }
function smooth(t) { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); }
function easeOut(t) { t = clamp(t, 0, 1); return 1 - (1 - t) * (1 - t); }
function easeIn(t) { t = clamp(t, 0, 1); return t * t; }

// deterministic pseudo-random (so every screening is identical)
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function canvasTex(w, h, draw, repeat) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.anisotropy = 8;
  if (repeat) t.repeat.set(repeat[0], repeat[1]);
  return t;
}

// piecewise keyframe track: [[time, value], ...] -> smooth value at t
function track(keys) {
  return (t) => {
    if (t <= keys[0][0]) return keys[0][1];
    for (let i = 0; i < keys.length - 1; i++) {
      const [t0, v0] = keys[i], [t1, v1] = keys[i + 1];
      if (t <= t1) return lerp(v0, v1, smooth((t - t0) / (t1 - t0)));
    }
    return keys[keys.length - 1][1];
  };
}

// gaussian bump centred at c with width w, height h
function bump(t, c, w, h) {
  const d = (t - c) / w;
  return h * Math.exp(-d * d * 4);
}

// ----------------------------------------------------------------------------
// renderer / scene
// ----------------------------------------------------------------------------
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
document.getElementById('stage').appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1612);

const camera = new THREE.PerspectiveCamera(40, innerWidth / innerHeight, 0.02, 60);

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ----------------------------------------------------------------------------
// lighting — late-afternoon sun through the window + warm bedside lamp
// ----------------------------------------------------------------------------
const sun = new THREE.DirectionalLight(0xffd9a8, 3.4);
sun.position.set(1.4, 2.6, -6.5);            // outside, beyond the back wall window
sun.target.position.set(-0.4, 0, 1.0);       // raking across the floor
scene.add(sun, sun.target);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -3.4; sun.shadow.camera.right = 3.4;
sun.shadow.camera.top = 3.2;  sun.shadow.camera.bottom = -3.2;
sun.shadow.camera.near = 1;   sun.shadow.camera.far = 14;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.015;

const sky = new THREE.HemisphereLight(0x9ab0cf, 0x4a3a2c, 0.55);
scene.add(sky);

// soft bounce off the sunlit floor back up at the room
const bounce = new THREE.DirectionalLight(0xffe6c8, 0.28);
bounce.position.set(0.5, -1, 2.5);
scene.add(bounce);

// bedside lamp (built with the nightstand below; light source here)
const lampLight = new THREE.PointLight(0xffc890, 0.9, 4.5, 2);
lampLight.position.set(-2.05, 0.86, 0.95);
lampLight.castShadow = true;
lampLight.shadow.mapSize.set(512, 512);
lampLight.shadow.bias = -0.002;
scene.add(lampLight);

// ----------------------------------------------------------------------------
// THE SET — a child's bedroom, 5.2 m × 4.2 m
//   floor: x ∈ [-2.6, 2.6], z ∈ [-2.1, 2.1] ;  walls 2.7 m high
//   window on the back wall (z = -2.1) ;  bed against the left wall
// ----------------------------------------------------------------------------
const set = new THREE.Group();
scene.add(set);

// ---- wood plank floor --------------------------------------------------
const floorTex = canvasTex(1024, 1024, (g, w, h) => {
  const r = rng(7);
  const plankH = h / 8;
  for (let row = 0; row < 8; row++) {
    const off = (row % 2) * w * 0.33;
    for (let px = -1; px < 3; px++) {
      const x0 = px * w * 0.5 + off, base = 96 + r() * 38;
      g.fillStyle = `rgb(${base + 30 | 0},${base * 0.72 | 0},${base * 0.46 | 0})`;
      g.fillRect(x0, row * plankH, w * 0.5 - 3, plankH - 3);
      // grain
      g.globalAlpha = 0.16;
      for (let i = 0; i < 22; i++) {
        g.strokeStyle = r() > 0.5 ? '#52391f' : '#a87b4d';
        g.lineWidth = 1 + r() * 1.5;
        const y = row * plankH + r() * plankH;
        g.beginPath();
        g.moveTo(x0, y);
        g.bezierCurveTo(x0 + w * 0.15, y + (r() - 0.5) * 9, x0 + w * 0.3, y + (r() - 0.5) * 9, x0 + w * 0.5, y);
        g.stroke();
      }
      g.globalAlpha = 1;
    }
  }
  // gaps between planks
  g.fillStyle = '#241509';
  for (let row = 0; row <= 8; row++) g.fillRect(0, row * plankH - 2, w, 3);
}, [2.4, 2]);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(5.2, 4.2),
  new THREE.MeshStandardMaterial({ map: floorTex, roughness: 0.55, metalness: 0.05 })
);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
set.add(floor);

// ---- walls ---------------------------------------------------------------
const wallMat = new THREE.MeshStandardMaterial({
  map: canvasTex(512, 512, (g, w, h) => {
    g.fillStyle = '#b9c4b1';                       // soft sage paint
    g.fillRect(0, 0, w, h);
    const r = rng(3); g.globalAlpha = 0.05;
    for (let i = 0; i < 1600; i++) {
      g.fillStyle = r() > 0.5 ? '#fff' : '#5a6455';
      g.fillRect(r() * w, r() * h, 2, 2);
    }
  }, [3, 2]),
  roughness: 0.95
});

function wall(wd, ht, x, y, z, ry) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(wd, ht), wallMat);
  m.position.set(x, y, z); m.rotation.y = ry;
  m.receiveShadow = true;
  set.add(m);
  return m;
}
wall(5.2, 2.7, 0, 1.35, 2.1, Math.PI);       // front (behind most cameras)
wall(4.2, 2.7, -2.6, 1.35, 0, Math.PI / 2);  // left
wall(4.2, 2.7, 2.6, 1.35, 0, -Math.PI / 2);  // right

// back wall with a window hole — built from 4 panels around the opening
// window opening: x ∈ [0.1, 1.5], y ∈ [0.95, 2.25]
{
  const z = -2.1;
  wall(2.7, 2.7, -1.25, 1.35, z, 0);                 // left of window
  wall(1.1, 2.7, 2.05, 1.35, z, 0);                  // right of window
  wall(1.4, 0.95, 0.8, 0.475, z, 0);                 // below sill
  wall(1.4, 0.45, 0.8, 2.475, z, 0);                 // above window
}

// ceiling
{
  const c = new THREE.Mesh(new THREE.PlaneGeometry(5.2, 4.2),
    new THREE.MeshStandardMaterial({ color: 0xe8e2d5, roughness: 1 }));
  c.rotation.x = Math.PI / 2; c.position.y = 2.7;
  set.add(c);
}

// baseboards
{
  const mat = new THREE.MeshStandardMaterial({ color: 0xe6e0d2, roughness: 0.8 });
  const mk = (wd, x, z, ry) => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(wd, 0.09, 0.018), mat);
    b.position.set(x, 0.045, z); b.rotation.y = ry;
    b.castShadow = b.receiveShadow = true;
    set.add(b);
  };
  mk(5.2, 0, -2.09, 0); mk(5.2, 0, 2.09, 0);
  mk(4.2, -2.59, 0, Math.PI / 2); mk(4.2, 2.59, 0, Math.PI / 2);
}

// ---- the window: frame, glass, evening sky, sheer curtains ---------------
{
  const g = new THREE.Group();
  g.position.set(0.8, 1.6, -2.1);
  const frameMat = new THREE.MeshStandardMaterial({ color: 0xf2ede2, roughness: 0.6 });
  const fr = (w, h, x, y, z = 0) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, 0.07), frameMat);
    m.position.set(x, y, z); m.castShadow = m.receiveShadow = true; g.add(m);
  };
  fr(1.5, 0.07, 0, 0.665); fr(1.5, 0.07, 0, -0.665);
  fr(0.07, 1.4, -0.715, 0); fr(0.07, 1.4, 0.715, 0);
  fr(0.05, 1.33, 0, 0);                       // vertical mullion
  fr(1.43, 0.05, 0, 0);                       // horizontal mullion
  fr(1.62, 0.05, 0, -0.71, 0.045);            // sill

  // glass
  const glass = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 1.33),
    new THREE.MeshPhysicalMaterial({ color: 0xcfe0ee, transparent: true, opacity: 0.12, roughness: 0.05 }));
  g.add(glass);

  // sky backdrop outside — warm gradient evening sky
  const skyTex = canvasTex(256, 256, (gc, w, h) => {
    const gr = gc.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, '#7e9fc4'); gr.addColorStop(0.55, '#e8b87a');
    gr.addColorStop(0.78, '#f4a85e'); gr.addColorStop(1, '#c97b3e');
    gc.fillStyle = gr; gc.fillRect(0, 0, w, h);
  });
  const skyPlane = new THREE.Mesh(new THREE.PlaneGeometry(4, 3),
    new THREE.MeshBasicMaterial({ map: skyTex }));
  skyPlane.position.z = -1.4;
  g.add(skyPlane);

  // sheer curtains either side
  const curMat = new THREE.MeshStandardMaterial({
    color: 0xfff6e0, transparent: true, opacity: 0.55, roughness: 1, side: THREE.DoubleSide
  });
  for (const sx of [-0.85, 0.85]) {
    const cur = new THREE.Mesh(new THREE.PlaneGeometry(0.42, 1.8, 8, 1), curMat);
    const pos = cur.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++)
      pos.setZ(i, Math.sin(pos.getX(i) * 28) * 0.035);   // gentle folds
    cur.position.set(sx, 0.1, 0.09);
    g.add(cur);
  }
  // curtain rod
  const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 2.2),
    new THREE.MeshStandardMaterial({ color: 0x6e5336, roughness: 0.4, metalness: 0.3 }));
  rod.rotation.z = Math.PI / 2; rod.position.set(0, 1.02, 0.1);
  g.add(rod);
  set.add(g);
}

// ---- light shaft + dust motes through the window --------------------------
{
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.55, 1.25, 4.6, 4, 1, true),
    new THREE.MeshBasicMaterial({
      color: 0xffdba6, transparent: true, opacity: 0.05,
      side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending
    })
  );
  shaft.scale.x = 1.5;
  shaft.position.set(0.45, 1.1, -0.9);
  shaft.rotation.set(0.55, 0, 0.1);
  set.add(shaft);
}

const motes = (() => {
  const N = 260, r = rng(42);
  const geo = new THREE.BufferGeometry();
  const p = new Float32Array(N * 3), seed = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    p[i * 3] = 0.4 + (r() - 0.5) * 1.6;
    p[i * 3 + 1] = 0.05 + r() * 2.0;
    p[i * 3 + 2] = -1.9 + r() * 2.4;
    seed[i] = r() * 100;
  }
  geo.setAttribute('position', new THREE.BufferAttribute(p, 3));
  const pts = new THREE.Points(geo, new THREE.PointsMaterial({
    color: 0xffe9c0, size: 0.008, transparent: true, opacity: 0.55,
    depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
  }));
  pts.userData = { seed };
  scene.add(pts);
  return pts;
})();

// ---- the bed (against the left wall) --------------------------------------
//  occupies x ∈ [-2.45, -1.30], z ∈ [-1.62, 0.42]; 16 cm clearance underneath
{
  const g = new THREE.Group();
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x8a5a33, roughness: 0.6 });
  const cast = m => { m.castShadow = m.receiveShadow = true; return m; };

  // legs
  for (const [lx, lz] of [[-2.38, -1.55], [-1.37, -1.55], [-2.38, 0.35], [-1.37, 0.35]]) {
    const leg = cast(new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.025, 0.16), woodMat));
    leg.position.set(lx, 0.08, lz); g.add(leg);
  }
  // frame box + mattress
  const frame = cast(new THREE.Mesh(new THREE.BoxGeometry(1.15, 0.12, 2.04), woodMat));
  frame.position.set(-1.875, 0.22, -0.6); g.add(frame);
  const mattress = cast(new THREE.Mesh(
    new THREE.BoxGeometry(1.08, 0.17, 1.98),
    new THREE.MeshStandardMaterial({ color: 0xf4efe2, roughness: 0.95 })));
  mattress.position.set(-1.875, 0.365, -0.6); g.add(mattress);

  // rumpled quilt — displaced plane draped over the mattress
  const quiltGeo = new THREE.PlaneGeometry(1.3, 1.6, 26, 26);
  {
    const pos = quiltGeo.attributes.position, r = rng(11);
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i);
      pos.setZ(i, Math.sin(x * 9 + 1) * 0.013 + Math.sin(y * 7) * 0.016 + (r() - 0.5) * 0.008);
    }
    quiltGeo.computeVertexNormals();
  }
