// ---- building blocks (the obstacle the mouse will plow through) -------------
//  each block stores its rest transform and gets a scripted tumble at t≈37.4 s
const blocks = [];
{
  const r = rng(99);
  const colors = [0xd84848, 0x4888d8, 0xe8b840, 0x48a868, 0xa060c0];
  const layout = [   // [x, z, stackY, ry]
    [1.32, -0.92, 0, 0.3], [1.46, -0.80, 0, 1.2], [1.30, -0.74, 0, 0.8],
    [1.38, -0.86, 1, 0.5], [1.52, -0.96, 0, 2.0], [1.22, -0.96, 0, 1.6],
    [1.44, -0.70, 0, 0.1], [1.36, -0.80, 2, 1.0],
  ];
  for (let i = 0; i < layout.length; i++) {
    const [x, z, sy, ry] = layout[i];
    const s = 0.055;
    const b = new THREE.Mesh(new THREE.BoxGeometry(s, s, s),
      new THREE.MeshStandardMaterial({ color: colors[i % colors.length], roughness: 0.5 }));
    b.castShadow = b.receiveShadow = true;
    b.position.set(x, s / 2 + sy * s, z);
    b.rotation.y = ry;
    set.add(b);
    // scripted tumble: direction away from the mouse's travel, deterministic
    blocks.push({
      mesh: b, rest: b.position.clone(), restRot: ry,
      vx: (r() - 0.3) * 1.4, vz: (r() - 0.5) * 1.6, vy: 0.9 + r() * 1.1,
      spin: (r() - 0.5) * 18, delay: r() * 0.12
    });
  }
}

const BLOCK_HIT_T = 37.4;   // the moment the mouse plows through

function updateBlocks(t) {
  for (const b of blocks) {
    const lt = t - BLOCK_HIT_T - b.delay;
    if (lt <= 0) {
      b.mesh.position.copy(b.rest);
      b.mesh.rotation.set(0, b.restRot, 0);
      continue;
    }
    // ballistic arc with one damped bounce, then rest
    const g = 9.8, tHit = 2 * b.vy / g;
    let x, y, z, spin;
    if (lt < tHit) {
      x = b.rest.x + b.vx * lt; z = b.rest.z + b.vz * lt;
      y = b.rest.y + b.vy * lt - 0.5 * g * lt * lt;
      spin = b.spin * lt;
    } else {
      const lt2 = lt - tHit, vy2 = b.vy * 0.35, tHit2 = 2 * vy2 / g;
      const cl2 = Math.min(lt2, tHit2);
      x = b.rest.x + b.vx * (tHit + cl2 * 0.4);
      z = b.rest.z + b.vz * (tHit + cl2 * 0.4);
      y = 0.0275 + Math.max(0, vy2 * cl2 - 0.5 * g * cl2 * cl2);
      spin = b.spin * (tHit + cl2 * 0.5);
    }
    b.mesh.position.set(x, Math.max(y, 0.0275), z);
    b.mesh.rotation.set(spin * 0.7, b.restRot + spin, spin * 0.3);
  }
}

