// ---- Pip's route: toy chest → rug loop → under the bed → along the back wall
//      → through the blocks → wide arc → dies by the nightstand
const mousePts = [
  v3(1.90, -1.30), v3(1.10, -1.00), v3(0.50, -0.20), v3(0.60, 0.70),
  v3(-0.30, 1.10), v3(-1.00, 0.60), v3(-1.30, -0.15),                  // 6: bed approach
  v3(-1.80, -0.60), v3(-1.95, -1.15),                                  // 7-8: under the bed
  v3(-1.35, -1.82),                                                    // 9: pops out at the corner
  v3(0.00, -1.80), v3(1.05, -1.42),                                    // 10-11: along the back wall
  v3(1.38, -0.84),                                                     // 12: through the blocks!
  v3(1.70, 0.10), v3(1.10, 1.25), v3(0.10, 1.62), v3(-0.85, 1.42),
  v3(-1.50, 0.92),                                                     // 17: final stop
];
const mouseCurve = new THREE.CatmullRomCurve3(mousePts, false, 'centripetal', 0.3);
const mu = i => i / (mousePts.length - 1);   // curve param at waypoint i

// progress along the curve over film time (the heart of the pacing)
const mouseU = track([
  [0.0, 0],            // asleep by the toy chest
  [6.5, 0],            // ...the key has been turning all along
  [9.0, mu(1) * 0.5],  // first lurch
  [13.0, mu(2)],       // gathers speed
  [17.5, mu(4)],       // flying around the rug
  [21.5, mu(5)],
  [24.5, mu(6)],       // reaches the bed
  [27.0, mu(7)],       // disappears underneath (slower in the dark)
  [29.5, mu(9)],       // pops out at the corner
  [33.0, mu(10)],      // sprints through the window light
  [36.0, mu(11)],
  [37.6, mu(12)],      // CRASH — through the blocks
  [41.0, mu(13)],
  [45.0, mu(14)],
  [49.0, mu(15)],      // the spring is fading...
  [53.5, mu(16)],
  [57.0, mu(17)],      // ...stops
]);

// how much spring is left (drives key speed, ticking, waddle energy)
