  v3(1.00, -1.38), v3(1.32, -0.80),                                    // 8-9: leaps the blocks
  v3(1.62, 0.10), v3(1.12, 1.18), v3(0.15, 1.52), v3(-0.72, 1.35),
  v3(-1.32, 0.95),                                                     // 14: the pounce
];
const catCurve = new THREE.CatmullRomCurve3(catPts, false, 'centripetal', 0.3);
const cu = i => i / (catPts.length - 1);

const catU = track([
  [0.0, 0],
  [12.5, 0],            // still waking up / wiggling haunches
  [15.0, cu(1)],        // POUNCE — the chase is on
  [18.5, cu(3)],
  [21.0, cu(4)],
  [24.0, cu(5)],        // skids to a halt at the bed
  [29.8, cu(5)],        // peeking underneath... where did he go?
  [33.5, cu(6)],        // spots him! cuts across the room
  [36.5, cu(7)],
  [38.8, cu(8)],
  [40.2, cu(9)],        // leap over the scattered blocks
  [44.0, cu(10)],
  [48.5, cu(11)],
  [53.0, cu(12)],
  [56.5, cu(13)],
  [58.0, cu(14)],       // soft final pounce
]);

// scratch vectors
const _p = new THREE.Vector3(), _q = new THREE.Vector3(), _t = new THREE.Vector3();

function headingOf(curve, u, eps = 0.004) {
  curve.getPoint(clamp(u + eps, 0, 1), _q);
  curve.getPoint(clamp(u - eps, 0, 1), _t);
  return Math.atan2(_q.x - _t.x, _q.z - _t.z);
}

let mouseYaw = 0, catYaw = 0, catHopPhase = 0, lastMouseU = 0, lastCatU = 0;
let mouseDist = 0, keyAngle = 0;

function angleLerp(a, b, t) {
  let d = b - a;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  return a + d * t;
}

// place a chain of segments trailing behind an actor, with a sinuous wave
function layTail(segs, origin, yaw, baseY, spread, wave, lift) {
  for (let i = 0; i < segs.length; i++) {
    const f = (i + 1) / segs.length;
    const back = -spread * (i + 1);
    const sway = Math.sin(wave - i * 0.7) * 0.02 * f;
    segs[i].position.set(
      origin.x + Math.sin(yaw) * back + Math.cos(yaw) * sway,
      baseY + Math.sin(f * 2.4) * lift * f,
      origin.z + Math.cos(yaw) * back - Math.sin(yaw) * sway
    );
  }
}

// ---- per-frame actor update -------------------------------------------------
function updateActors(t, dt) {
  // ======================= Pip the mouse =======================
  const u = mouseU(t);
  mouseCurve.getPoint(u, _p);
  const speed = Math.abs(u - lastMouseU) / Math.max(dt, 1e-4) * 14;   // rough m/s
  lastMouseU = u;
  mouseDist += speed * dt;

  const targetYaw = speed > 0.02 ? headingOf(mouseCurve, u) : mouseYaw;
  mouseYaw = angleLerp(mouseYaw, targetYaw, clamp(dt * 7, 0, 1));

  const energy = mouseEnergy(t);
  const waddle = Math.sin(mouseDist * 30) * 0.06 * clamp(speed, 0, 1) * (0.4 + energy);

  mouse.position.set(_p.x, 0, _p.z);
  mouse.rotation.set(0, mouseYaw, waddle);
  // little nose-down lurch when starting, tip-over wobble at the very end
  mouse.rotation.x = -clamp(speed, 0, 1) * 0.05
    + bump(t, 8.6, 0.8, 0.12)                       // the first lurch rocks it back
    + bump(t, 58.2, 1.2, -0.18);                    // boop! rocks on its nose, settles

  // key: spins fast while wound, dies at the end
  keyAngle += dt * (3 + 9 * energy) * (t < 6.5 ? 1.6 : (0.4 + clamp(speed, 0, 1)));
  if (energy <= 0) keyAngle += 0; // stopped
  mouseKey.rotation.z = keyAngle;

  for (const w of mouseWheels) w.rotation.x += speed * dt / 0.016;

  layTail(mouseTail, mouse.position, mouseYaw + Math.PI, 0.028, 0.014,
    mouseDist * 18, 0.012);
  // tail segments live in world space relative math above but are children of
  // mouse group — convert: simplest is to park them in scene space instead
  // (they were added to the mouse group; reparent once)
  // -- handled at init below --

  // ======================= Biscuit the cat =======================
  const cuv = catU(t);
  catCurve.getPoint(cuv, _q);
  const catSpeed = Math.abs(cuv - lastCatU) / Math.max(dt, 1e-4) * 12;
  lastCatU = cuv;

  const catTargetYaw = catSpeed > 0.02 ? headingOf(catCurve, cuv) : catYaw;
  catYaw = angleLerp(catYaw, catTargetYaw, clamp(dt * 6, 0, 1));

  catHopPhase += clamp(catSpeed, 0, 2.2) * dt * 11;
  const hop = Math.max(0, Math.sin(catHopPhase)) * 0.05 * clamp(catSpeed, 0, 1);

  // the big leap over the blocks
  const leap = bump(t, 39.6, 0.55, 0.21);
  // the opening pounce
  const pounceLaunch = bump(t, 13.1, 0.45, 0.12);
  // final soft pounce onto the dead mouse
  const finalPounce = bump(t, 57.6, 0.5, 0.1);

  cat.position.set(_q.x, hop + leap + pounceLaunch + finalPounce, _q.z);
  cat.rotation.y = catYaw;
  // pitch with hops and leaps
  cat.rotation.x = -Math.sin(catHopPhase) * 0.07 * clamp(catSpeed, 0, 1)
    - bump(t, 39.45, 0.4, 0.3) + bump(t, 39.85, 0.4, 0.25);

  // -------- head acting --------
  // idle: asleep (head low). 5–9 s: lifts, tracks the mouse. peek: head dips low.
  const wake = smooth((t - 5.5) / 2.5);
  const peek = smooth((t - 24.6) / 0.8) * (1 - smooth((t - 29.3) / 1.2));
  const headLowSleep = (1 - wake) * 0.55;

  // track the mouse with the head whenever awake and not peeking
  _t.subVectors(mouse.position, cat.position);
  const lookYawWorld = Math.atan2(_t.x, _t.z);
  let lookLocal = lookYawWorld - catYaw;
  while (lookLocal > Math.PI) lookLocal -= 2 * Math.PI;
  while (lookLocal < -Math.PI) lookLocal += 2 * Math.PI;
  lookLocal = clamp(lookLocal, -0.85, 0.85) * wake * (1 - peek);

  catHead.rotation.y = lookLocal;
  catHead.rotation.x = headLowSleep + peek * 0.85
    - finalPounce * 3                                     // nose down for the boop
    + bump(t, 12.2, 0.5, -0.25);                          // alert "!" before pouncing
  catHead.position.y = 0.205 - headLowSleep * 0.06 - peek * 0.1;

  // ears: flatten slightly at full sprint, perk on alert
  const perk = bump(t, 11.9, 0.8, 0.25);
  catEarL.rotation.z = 0.28 + perk - clamp(catSpeed, 0, 1) * 0.12;
  catEarR.rotation.z = -0.28 - perk + clamp(catSpeed, 0, 1) * 0.12;

  // butt-wiggle before the pounce (12.4–13.0 s) — every cat does it
  const wiggle = (t > 12.2 && t < 13.0) ? Math.sin(t * 40) * 0.05 : 0;
  cat.rotation.z = wiggle + Math.sin(catHopPhase) * 0.03 * clamp(catSpeed, 0, 1);

  // legs splay a little mid-hop
  for (let i = 0; i < catLegs.length; i++) {
    const front = i < 2 ? 1 : -1;
    catLegs[i].rotation.x = Math.sin(catHopPhase + front) * 0.5 * clamp(catSpeed, 0, 1)
      + leap * front * 2.2;
  }

  // tail: streams when running, slow flick when idle, agitated at the bed
  const flick = peek > 0.3 ? Math.sin(t * 9) * 0.06 : Math.sin(t * 1.8) * 0.025;
  layTailCat(t, catSpeed, flick);
}

// cat tail in cat-local space (segments are children of the cat group)
function layTailCat(t, speed, flick) {
  for (let i = 0; i < catTailSegs.length; i++) {
    const f = (i + 1) / catTailSegs.length;
    const run = clamp(speed, 0, 1);
    catTailSegs[i].position.set(
      Math.sin(t * 2.2 + i * 0.6) * 0.012 + flick * i,
      0.1 + f * (0.16 - run * 0.1) * Math.sin(f * 1.8 + run),
      -0.11 - f * 0.13
    );
  }
}

// mouse tail segments: keep them as children of the scene for world-space math
for (const seg of mouseTail) { mouse.remove(seg); scene.add(seg); }

// ============================================================================
//  CINEMATOGRAPHY — the 10-shot cut list
//  each shot positions the camera for local time s ∈ [0, dur]
// ============================================================================

const _look = new THREE.Vector3();
const _cam = new THREE.Vector3();

function midpoint(a, b, bias = 0.5) {
  return _look.copy(a).lerp(b, bias);
}

const shots = [
  // 1 — ESTABLISHING. High front-right corner; slow push toward the window
  //     light. The room at golden hour. The faint tick of the key.
  {
    start: 0, end: 7.0, fov: 42, shake: 0,
    update(s, n) {
      _cam.set(2.1 - n * 0.55, 1.55 - n * 0.28, 1.85 - n * 0.5);
      camera.position.copy(_cam);
      camera.lookAt(-0.25, 0.42 - n * 0.18, -0.75);
    }
  },
  // 2 — INSERT, floor level. The mouse by the toy chest, key turning.
  //     It lurches awake and rolls off. Camera pans to follow.
  {
    start: 7.0, end: 12.4, fov: 30, shake: 0.0006,
    update(s, n) {
      camera.position.set(1.45, 0.085, -0.78);
      midpoint(mouse.position, mouse.position);
      camera.lookAt(_look.x, 0.06, _look.z);
    }
  },
  // 3 — THE CAT. Static medium shot on the rug: ears perk, butt wiggles,
  //     pounce out of frame.
  {
    start: 12.4, end: 16.4, fov: 33, shake: 0.0005,
    update(s, n) {
      camera.position.set(-0.7, 0.22, 1.45);
      camera.lookAt(0.15, 0.13, 0.25);
    }
  },
  // 4 — LOW TRACKING SHOT. Dolly alongside the chase around the rug,
  //     both toys in frame, floor blurring past.
  {
    start: 16.4, end: 24.2, fov: 36, shake: 0.0012,
    update(s, n) {
      midpoint(mouse.position, cat.position, 0.42);
      const ang = 2.6 - n * 1.4;
      camera.position.set(
        _look.x + Math.cos(ang) * 0.85,
        0.11 + n * 0.05,
        _look.z + Math.sin(ang) * 0.85
      );
      camera.lookAt(_look.x, 0.08, _look.z);
    }
  },
  // 5 — UNDER THE BED. Camera lies in the dust beneath the bed. The mouse
  //     races toward the lens; behind it, the cat's face drops into the
  //     gap of light, peering in. He can't follow.
  {
    start: 24.2, end: 29.8, fov: 38, shake: 0.0008,
    update(s, n) {
      camera.position.set(-2.18, 0.075, -1.55);
      midpoint(mouse.position, cat.position, smooth(n * 1.6) * 0.55);
      camera.lookAt(_look.x, 0.07, _look.z);
    }
  },
  // 6 — THE WINDOW LIGHT. Wide and locked off, from the rug, looking at the
  //     back wall: the mouse pops out of the corner and sprints through the
  //     shaft of golden light; the cat vaults across frame to cut him off.
  {
    start: 29.8, end: 36.6, fov: 40, shake: 0,
    update(s, n) {
      camera.position.set(0.35, 0.32, 1.5);
      camera.lookAt(0.1 + n * 0.35, 0.28, -1.9);
    }
  },
  // 7 — THE BLOCKS. Handheld at floor level next to the block tower.
  //     The mouse plows straight through; blocks rain past the lens;
  //     the cat sails over the wreckage.
  {
    start: 36.6, end: 41.2, fov: 31, shake: 0.0035,
    update(s, n) {
      camera.position.set(1.95, 0.1, -0.45);
      midpoint(mouse.position, cat.position, 0.3 + n * 0.3);
      camera.lookAt(_look.x, 0.07 + bump(s, 1.2, 0.6, 0.05), _look.z);
    }
  },
  // 8 — CRANE. Rising overhead shot, looking down on the final arc as the
  //     gap closes. The whole room and the whole story in one frame.
  {
    start: 41.2, end: 48.6, fov: 44, shake: 0,
    update(s, n) {
      midpoint(mouse.position, cat.position, 0.5);
      camera.position.set(_look.x * 0.4 + 0.3, 1.7 + n * 0.7, _look.z * 0.4 + 1.0);
      camera.lookAt(_look.x, 0, _look.z);
    }
  },
  // 9 — THE SPRING RUNS OUT. Low frontal on the mouse, lamp-lit. It slows,
  //     staggers... the cat looms into the background, closing softly.
  {
    start: 48.6, end: 55.4, fov: 28, shake: 0.0008,
    update(s, n) {
      const ahead = mouseYaw;
      camera.position.set(
        mouse.position.x + Math.sin(ahead) * (0.5 - n * 0.12),
        0.075,
        mouse.position.z + Math.cos(ahead) * (0.5 - n * 0.12)
      );
      midpoint(mouse.position, cat.position, 0.25);
      camera.lookAt(_look.x, 0.06, _look.z);
    }
  },
  // 10 — FIN. Slow push-in two-shot by the nightstand. The cat boops the
  //      silent mouse with his nose. The key gives one last half-turn.
  //      Fade to black.
  {
    start: 55.4, end: 60.0, fov: 26, shake: 0.0004,
    update(s, n) {
      camera.position.set(-0.55 - n * 0.18, 0.16 - n * 0.05, 1.85 - n * 0.3);
      midpoint(mouse.position, cat.position, 0.45);
      camera.lookAt(_look.x, 0.09, _look.z);
    }
  },
];

let shakeSeed = 0;
function updateCamera(t) {
  for (const sh of shots) {
    if (t >= sh.start && t < sh.end) {
      const s = t - sh.start, n = s / (sh.end - sh.start);
      camera.fov = sh.fov;
      sh.update(s, n);
      if (sh.shake) {       // gentle handheld noise
        shakeSeed += 0.13;
        camera.position.x += Math.sin(shakeSeed * 1.1) * sh.shake * 8;
        camera.position.y += Math.sin(shakeSeed * 1.7 + 2) * sh.shake * 6;
        camera.rotation.z += Math.sin(shakeSeed * 0.9 + 4) * sh.shake * 1.5;
      }
      camera.updateProjectionMatrix();
      return;
    }
  }
}

// ============================================================================
//  SOUND — the wind-up tick, synthesized
// ============================================================================
let audio = null;
function initAudio() {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  const master = ctx.createGain();
  master.gain.value = 0.16;
  master.connect(ctx.destination);

  // soft room tone: filtered noise
  const len = ctx.sampleRate * 2;
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * 0.25;
  const noise = ctx.createBufferSource();
  noise.buffer = buf; noise.loop = true;
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass'; lp.frequency.value = 320;
  const ng = ctx.createGain(); ng.gain.value = 0.05;
  noise.connect(lp).connect(ng).connect(master);
  noise.start();

  audio = { ctx, master, lastTick: 0 };
}

function tick(strength, freq) {
  if (!audio) return;
  const { ctx, master } = audio;
  const o = ctx.createOscillator();
  o.type = 'square'; o.frequency.value = freq;
  const g = ctx.createGain();
  g.gain.setValueAtTime(strength, ctx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.03);
  o.connect(g).connect(master);
  o.start(); o.stop(ctx.currentTime + 0.04);
}

let tickAccum = 0;
function updateAudio(t, dt) {
  if (!audio) return;
  const energy = mouseEnergy(t);
  if (energy <= 0.005) return;
  const rate = 4 + energy * 14;          // ticks per second
  tickAccum += dt * rate;
  if (tickAccum >= 1) {
    tickAccum = 0;
    tick(0.05 + energy * 0.05, 1900 + energy * 700);
  }
  // the block crash
  if (t > BLOCK_HIT_T && t < BLOCK_HIT_T + 0.05 && !audio.crashed) {
    audio.crashed = true;
    for (let i = 0; i < 6; i++)
      setTimeout(() => tick(0.3, 240 + Math.random() * 320), i * 55 + Math.random() * 40);
  }
}

// ============================================================================
//  OVERLAYS — titles, fades, film grain, timecode
// ============================================================================
const fader = document.getElementById('fader');
const titleMain = document.getElementById('titleMain');
const titleSub = document.getElementById('titleSub');
const titleFin = document.getElementById('titleFin');
const tcEl = document.getElementById('tc');

function updateOverlays(t) {
  // fade in from black over the establishing shot; fade out at the end
  let black = 0;
  if (t < 2.2) black = 1 - smooth(t / 2.2);
  if (t > 58.2) black = smooth((t - 58.2) / 1.6);
  fader.style.opacity = black.toFixed(3);

  // main title floats over the establishing shot
  const tA = smooth((t - 1.2) / 1.2) * (1 - smooth((t - 5.2) / 1.0));
  titleMain.style.opacity = tA.toFixed(3);
  titleSub.style.opacity = (tA * 0.8).toFixed(3);

  // fin
  titleFin.style.opacity = t > 59 ? smooth((t - 59) / 0.8).toFixed(3) : 0;

  const ss = Math.floor(t), ff = Math.floor((t % 1) * 24);
  tcEl.textContent = `00:${String(ss).padStart(2, '0')}:${String(ff).padStart(2, '0')}`;
}

// film grain on a tiny overlay canvas
const grainCv = document.getElementById('grain');
const grainCtx = grainCv.getContext('2d');
grainCv.width = 256; grainCv.height = 256;
grainCv.style.width = '100%'; grainCv.style.height = '100%';
function updateGrain() {
  const img = grainCtx.createImageData(256, 256);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const v = Math.random() * 255;
    d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 26;
  }
  grainCtx.putImageData(img, 0, 0);
}

// ============================================================================
//  PLAYBACK
// ============================================================================
let playing = false, filmTime = 0, lastReal = 0;

function frame(now) {
  requestAnimationFrame(frame);
  const dt = Math.min((now - lastReal) / 1000, 0.05);
  lastReal = now;
  if (!playing) { renderer.render(scene, camera); return; }

  filmTime += dt;
  const t = filmTime;

  if (t >= FILM_LENGTH + 1.5) { endFilm(); return; }

  updateActors(t, dt);
  updateBlocks(t);
  updateCamera(t);
  updateAudio(t, dt);
  updateOverlays(Math.min(t, FILM_LENGTH));
  if ((now | 0) % 2 === 0) updateGrain();

  // dust motes drift in the light
  {
    const pos = motes.geometry.attributes.position;
    const seed = motes.userData.seed;
    for (let i = 0; i < pos.count; i++) {
      pos.setY(i, pos.getY(i) + Math.sin(t * 0.4 + seed[i]) * 0.00012);
      pos.setX(i, pos.getX(i) + Math.cos(t * 0.3 + seed[i] * 2) * 0.0001);
    }
    pos.needsUpdate = true;
  }

  renderer.render(scene, camera);
}

const playWrap = document.getElementById('playWrap');
const playBtn = document.getElementById('playBtn');

function startFilm() {
  if (!audio) initAudio();
  if (audio && audio.ctx.state === 'suspended') audio.ctx.resume();
  if (audio) audio.crashed = false;
  filmTime = 0; tickAccum = 0;
  mouseYaw = headingOf(mouseCurve, 0.001);
  catYaw = Math.PI * 0.7;            // napping, facing vaguely toward the chest
  lastMouseU = 0; lastCatU = 0; mouseDist = 0; keyAngle = 0; catHopPhase = 0;
  playWrap.classList.add('hidden');
  playing = true;
}

function endFilm() {
  playing = false;
  fader.style.opacity = 1;
  titleFin.style.opacity = 0;
  playBtn.textContent = '↺  WATCH AGAIN';
  playWrap.classList.remove('hidden');
}

playBtn.addEventListener('click', startFilm);

// pre-position everything for the frame behind the menu
updateActors(0, 0.016);
updateCamera(0);
updateOverlays(0);
requestAnimationFrame((n) => { lastReal = n; requestAnimationFrame(frame); });
